"""Publish isolated source-profile construction and its retained limitations."""
from pathlib import Path
import json, hashlib, shutil
ROOT=Path(__file__).resolve().parents[1]
WORK=Path('./.local/station-realism')
OUT=ROOT/'notes/hall-bank-profiles'; OUT.mkdir(exist_ok=True)
load=lambda p:json.loads(p.read_text())
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
build=load(WORK/'hall-descents-11/report.json'); assembly=load(WORK/'hall-descents-assembly-11/report.json')
native=load(WORK/'hall-descents-native-05/report.json'); dedup=load(WORK/'hall-descents-11/dedup-proof.json')
assert native['summary']['pass'] and native['summary']['walks']==24 and native['summary']['rides']==4
assert native['nativeSha256']==load(WORK/'hall-descents-assembly-10/report.json')['outputs']['nativePanelsSha256']
assert dedup['pass'] and dedup['beforeNativeSha256']==load(WORK/'hall-descents-10/report.json')['outputs']['nativePanelsSha256']
assert dedup['afterNativeSha256']==build['outputs']['nativePanelsSha256']
files={'before.png':ROOT/'notes/hall-descents/close.png','after.png':WORK/'hall-descents-assembly-11/close/source.png','overview.png':WORK/'hall-descents-assembly-11/overview/source.png','component.json':WORK/'hall-descents-11/report.json','assembly.json':WORK/'hall-descents-assembly-11/report.json','native.json':WORK/'hall-descents-native-05/report.json','native-tested-assembly.json':WORK/'hall-descents-assembly-10/report.json','native-tested-component.json':WORK/'hall-descents-10/report.json','raw-profiles.json':WORK/'hall-bank-profiles-spec-02/spec.json','cut-profiles.json':WORK/'hall-bank-profiles-spec-08/spec.json','joins.json':WORK/'hall-bank-profiles-spec-08/joins-02.json','rejected-boolean-proof.json':WORK/'hall-descents-06/source-proof.json'}
for name in ['source-proof','geometry-proof','serialization-proof','motion-proof','dedup-proof','floor-interface-audit']:
 files[name+'.json']=WORK/f'hall-descents-11/{name}.json'
for name,src in files.items():shutil.copyfile(src,OUT/name)
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Central hall · source escalator profiles</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f2ec;color:#203b33;font:16px/1.55 system-ui}main{max-width:1320px;margin:auto;padding:32px}h1{font-size:clamp(32px,5vw,50px);line-height:1.1}nav{display:flex;gap:18px;flex-wrap:wrap}a{color:#17614d}.notice{background:#fff0d1;border-left:4px solid #ad7b1b;padding:18px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}figure{margin:0}img{width:100%;height:auto;display:block}figcaption,small{font-size:13px;color:#52675e}li{margin:8px 0}code{overflow-wrap:anywhere}@media(max-width:700px){main{padding:18px}.grid{grid-template-columns:1fr}}</style><main><nav><a href="../../index.html">Research library</a><a href="../HALL-BANK-PROFILES.md">Evidence note</a><a href="../hall-descents/index.html">Previous construction</a></nav><h1>Source-shaped rails, glass<br>and metal supports.</h1><p>Four working escalators now use the municipal model's bank profiles. The replacement reduces component triangles by 28.8%, while preserving all moving mechanisms.</p><p class="notice"><strong>Uninstalled candidate; floor joins unresolved.</strong> Retained landing plates overlap the upper floor by 0.0001045 m² and the lower floor by 0.0108304 m². The next change must reconcile those surfaces in both visual and collision geometry. Well lining, lower architecture, finishes and lighting remain unfinished.</p><h2>Same-camera comparison</h2><div class="grid"><figure><a href="before.png"><img src="before.png" alt="Previous escalator banks with coarse thick rails and simplified side profiles"></a><figcaption>Before: descent02. Fixed camera and inspection lighting.</figcaption></figure><figure><a href="after.png"><img src="after.png" alt="Revised banks with slimmer source handrails, shaped glass sides and steel support profiles"></a><figcaption>After: descent11. Source curves remain visibly faceted; materials are provisional.</figcaption></figure></div><h2>Hall assembly</h2><figure><a href="overview.png"><img src="overview.png" alt="Isolated hall with two paired escalator banks, three upper openings and lower landing"></a><figcaption>All 590 parent hall records remain unchanged. Empty surroundings and missing basement walls are still visible. This is an isolated inspection render, not a photographic match.</figcaption></figure><h2>Verified</h2><ul><li>3,404 original rail, glass and body faces remain exact after the declared height alignment. Support metal is cut around the working mechanisms; 28 independent sections pass the unchanged source-fidelity limits.</li><li>85 closed records, 45,266 triangles, four material batches and a 2.28 MB component GLB. This reduction does not establish a full-game frame-rate improvement.</li><li>128,000 motion samples pass; browser and native exports agree. Four lanes retain their prior paths, speeds, phases and comb transfers.</li><li>324 native support/headroom checks, 24 through walks and four standing rides passed on assembly10. Final assembly11 only deduplicates vertices: every native collision triangle and rendered position/normal corner is proven exactly equivalent.</li><li>The browser asset build passes. Full-station integration, course checks and the full-game performance/soak gates remain open.</li></ul><h2>Construction evidence</h2><p>The first Boolean trims closed successfully but altered source sections by up to 11 mm. Their failed receipt remains available. Exact triangle clipping passes without widening tolerances. A separate floor-interface audit still fails and is the next construction task.</p><nav>'''
for name,label in [('component.json','Component'),('assembly.json','Assembly'),('source-proof.json','Source fidelity'),('geometry-proof.json','Closed geometry'),('serialization-proof.json','Export agreement'),('motion-proof.json','Motion'),('native.json','Native walks and rides'),('dedup-proof.json','Exact dedup equivalence'),('floor-interface-audit.json','Unresolved floor joins'),('rejected-boolean-proof.json','Rejected Boolean result')]:page+=f'<a href="{name}">{label}</a>'
page+='''</nav><p><small>Municipal source geometry: Kyoto City, CC BY 4.0. Construction review: 28 September 2026. Full station remains courtyard life04/browser04. No final visual acceptance or deployment.</small></p></main></html>'''
(OUT/'index.html').write_text(page)
(OUT/'publication-receipt.json').write_text(json.dumps({'files':{n:sha(OUT/n)for n in [*files,'index.html']},'componentGlbSha256':build['outputs']['glbSha256'],'assemblyGlbSha256':assembly['outputs']['glbSha256'],'nativeSummary':native['summary'],'nativeTestedVersion':'assembly10; final11 exact triangle equivalence proven','fullStationChanged':False,'finalVisualAcceptance':False,'floorInterfacesPass':False},indent=2)+'\n')
print(OUT/'index.html')
